+// Namespace for concrete strategy implementations.
+// Adding a new algorithm means adding a class here and registering it — nothing else changes.
+class PathfindingStrategies {
+    private PathfindingStrategies() {}
+
+    static class FloydWarshall implements PathfindingStrategy {
+        public void compute(Graph g) {
+            int V = g.size();
+            for (int k = 0; k < V; k++)
